import React, { useState, useEffect } from 'react';
import Login from './pages/Login';
import PrincipalDashboard from './pages/PrincipalDashboard';
import TeacherDashboard from './pages/TeacherDashboard';
import StudentDashboard from './pages/StudentDashboard';
import AdminDashboard from './pages/AdminDashboard';
import Sidebar from './components/Sidebar';
import { User, UserRole } from './types';
import { logout } from './services/authService';
import { Menu } from 'lucide-react';

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [loading, setLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    // Check local storage for persistent session
    const storedUser = localStorage.getItem('nexus_user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
    setLoading(false);
  }, []);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    localStorage.setItem('nexus_user', JSON.stringify(loggedInUser));
    setCurrentPage('dashboard');
  };

  const handleLogout = async () => {
    await logout();
    setUser(null);
    localStorage.removeItem('nexus_user');
  };

  const handleNavigate = (page: string) => {
    setCurrentPage(page);
    setIsSidebarOpen(false); // Close sidebar on mobile when navigating
  };

  const renderDashboard = () => {
    if (!user) return null;

    if (user.role === UserRole.SUPREME_ADMIN) {
        return <AdminDashboard />;
    }

    switch (user.role) {
      case UserRole.PRINCIPAL:
        return <PrincipalDashboard currentPage={currentPage} />;
      case UserRole.TEACHER:
        return <TeacherDashboard currentPage={currentPage} currentUser={user} />;
      case UserRole.STUDENT:
        return <StudentDashboard user={user} currentPage={currentPage} />;
      default:
        return <div className="p-8">Role not supported yet.</div>;
    }
  };

  if (loading) {
    return <div className="min-h-screen flex items-center justify-center bg-slate-100 dark:bg-slate-900 dark:text-white">Loading...</div>;
  }

  if (!user) {
    return <Login onLoginSuccess={handleLogin} />;
  }

  // Ghost Admin Layout Override
  if (user.role === UserRole.SUPREME_ADMIN) {
      return (
          <div className="bg-slate-100 dark:bg-slate-950 min-h-screen font-sans text-base transition-colors duration-200">
             <div className="bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 px-8 py-3 flex justify-between items-center shadow-sm">
                 <div className="flex items-center gap-2">
                     <div className="w-8 h-8 bg-black rounded flex items-center justify-center text-white font-bold">A</div>
                     <span className="font-bold text-slate-800 dark:text-white">Admin Console</span>
                 </div>
                 <button onClick={handleLogout} className="text-red-600 text-sm font-medium hover:underline">Sign Out</button>
             </div>
             <div className="max-w-[95%] mx-auto p-4 md:p-8">
                 {renderDashboard()}
             </div>
          </div>
      )
  }

  // Standard App Layout
  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-950 font-sans text-base transition-colors duration-200">

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 left-0 right-0 bg-slate-900 text-white p-4 z-40 flex items-center justify-between shadow-md">
         <div className="flex items-center gap-3">
             <button onClick={() => setIsSidebarOpen(true)} className="p-1">
                 <Menu size={24} />
             </button>
             <span className="font-bold">School Management</span>
         </div>
      </div>

      <Sidebar 
        user={user} 
        onLogout={handleLogout} 
        currentPage={currentPage}
        onNavigate={handleNavigate}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className={`flex-1 transition-all duration-300 w-full min-w-0 md:ml-64 pt-16 md:pt-0 p-4 md:p-8`}>
        <div className="max-w-[95%] mx-auto">
          {renderDashboard()}
        </div>
      </main>
    </div>
  );
}

export default App;

