export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer 
} from 'recharts';
import { 
  Users, UserCheck, AlertTriangle, TrendingUp, Calendar, Plus, Search, BookOpen, Trash2, Pencil, Megaphone, Send, Globe, School
} from 'lucide-react';
import { WEEKLY_ATTENDANCE, CLASS_GRADES, SECTIONS_JUNIOR, SECTIONS_SENIOR } from '../constants';
import { User, UserRole, Announcement, HouseTeam, School as SchoolType, SchoolConfig } from '../types';
import { getStoredUsers, addUser, updateUser, removeUser, generateId, getStoredAnnouncements, addAnnouncement, deleteAnnouncement, getStoredSchools } from '../services/storage';

interface Props {
  currentPage?: string;
  currentUser?: User; 
}

const PrincipalDashboard: React.FC<Props> = ({ currentPage = 'dashboard' }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentSchoolConfig, setCurrentSchoolConfig] = useState<SchoolConfig | null>(null);

  const [showAddTeacher, setShowAddTeacher] = useState(false);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);

  // Teacher Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [teacherName, setTeacherName] = useState('');
  const [teacherID, setTeacherID] = useState('');
  const [teacherPassword, setTeacherPassword] = useState('');

  // Split Class State
  const [teacherGrade, setTeacherGrade] = useState('');
  const [teacherSection, setTeacherSection] = useState('');

  const [teacherSubject, setTeacherSubject] = useState('');
  const [teacherGender, setTeacherGender] = useState('Male'); 
  const [teacherDesignation, setTeacherDesignation] = useState('');
  const [teacherHouse, setTeacherHouse] = useState<HouseTeam>('');
  const [teacherEmail, setTeacherEmail] = useState('');
  const [teacherContact, setTeacherContact] = useState('');

  // Form Error
  const [formError, setFormError] = useState('');

  // Announcement Form State
  const [annTitle, setAnnTitle] = useState('');
  const [annContent, setAnnContent] = useState('');
  const [annAudience, setAnnAudience] = useState<'all' | 'student' | 'teacher'>('all');

  useEffect(() => {
    setUsers(getStoredUsers());

    // Get current user to know which School we are in
    const stored = localStorage.getItem('nexus_user');
    let userObj: User | null = null;
    if (stored) {
        userObj = JSON.parse(stored);
        setCurrentUser(userObj);

        // Fetch School Config
        if (userObj && userObj.schoolName) {
            const schools = getStoredSchools();
            const mySchool = schools.find(s => s.name === userObj?.schoolName);
            if (mySchool) setCurrentSchoolConfig(mySchool.config);
        }
    }

    const allAnn = getStoredAnnouncements();
    // Filter announcements: Show if Global (no schoolName) OR Matches User's School
    const relevantAnn = allAnn.filter(a => !a.schoolName || (userObj && a.schoolName === userObj.schoolName));
    setAnnouncements(relevantAnn);

  }, []);

  // Helper logic for class splitting
  const parseClassString = (classStr: string) => {
    if (!classStr) return { pGrade: '', pSection: '' };
    const parts = classStr.split('-');
    if (parts.length >= 2) {
        return { pGrade: parts[0], pSection: parts.slice(1).join('-') };
    }
    return { pGrade: classStr, pSection: '' };
  };

  const getSectionOptions = (grade: string) => {
      if (['11th', '12th'].includes(grade)) {
          if (currentSchoolConfig && currentSchoolConfig.streams.length > 0) {
              return currentSchoolConfig.streams;
          }
          return SECTIONS_SENIOR;
      }
      return SECTIONS_JUNIOR;
  };

  const getHouseOptions = () => {
      if (currentSchoolConfig && currentSchoolConfig.houseNames.length > 0) {
          return currentSchoolConfig.houseNames;
      }
      return ['Green', 'Blue', 'Yellow', 'Red'];
  };

  // --- TEACHER LOGIC ---
  const openAddModal = () => {
    setEditingId(null);
    setFormError('');
    setTeacherName('');
    setTeacherID('');
    setTeacherPassword('');
    setTeacherGrade('');
    setTeacherSection('');
    setTeacherSubject('');
    setTeacherGender('Male');
    setTeacherDesignation('');
    setTeacherHouse('');
    setTeacherEmail('');
    setTeacherContact('');
    setShowAddTeacher(true);
  };

  const openEditModal = (user: User) => {
    setEditingId(user.uid);
    setFormError('');
    setTeacherName(user.name);
    setTeacherID(user.schoolID);
    setTeacherPassword(user.password || '');

    const { pGrade, pSection } = parseClassString(user.assignedClass || '');
    setTeacherGrade(pGrade);
    setTeacherSection(pSection);

    setTeacherSubject(user.assignedSubject || '');
    setTeacherGender(user.gender || 'Male');
    setTeacherDesignation(user.designation || '');
    setTeacherHouse(user.house || '');
    setTeacherEmail(user.email || '');
    setTeacherContact(user.contactNumber || '');
    setShowAddTeacher(true);
  };

  const handleSaveTeacher = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');

    if (!currentUser?.schoolName) {
        setFormError("Error: You are not assigned to a valid School. Cannot add teachers.");
        return;
    }

    // Duplicate Check
    const isDuplicate = users.some(u => u.schoolID === teacherID && u.uid !== editingId);
    if (isDuplicate) {
        setFormError("School ID already exists. Please use a unique ID.");
        return;
    }

    // Allow empty if not assigned, but if grade selected, enforce section
    let fullClass = '';
    if (teacherGrade) {
        if (!teacherSection) {
            setFormError('Please select a section for the chosen grade.');
            return;
        }
        fullClass = `${teacherGrade}-${teacherSection}`;
    }

    if (editingId) {
      const updatedUser: User = {
         ...users.find(u => u.uid === editingId)!,
         name: teacherName,
         schoolID: teacherID,
         password: teacherPassword,
         assignedClass: fullClass,
         assignedSubject: teacherSubject,
         gender: teacherGender,
         designation: teacherDesignation,
         house: teacherHouse,
         email: teacherEmail,
         contactNumber: teacherContact,
         // Ensure School Name is consistent
         schoolName: currentUser.schoolName,
         avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(teacherName)}&background=8b5cf6&color=fff`
      };
      updateUser(updatedUser);
      alert(`Teacher ${teacherName} updated!`);
    } else {
      const newUser: User = {
        uid: generateId('u'),
        name: teacherName,
        schoolID: teacherID,
        role: UserRole.TEACHER,
        password: teacherPassword,
        assignedClass: fullClass,
        assignedSubject: teacherSubject,
        gender: teacherGender,
        designation: teacherDesignation,
        house: teacherHouse,
        email: teacherEmail,
        contactNumber: teacherContact,
        // Auto assign Principal's school
        schoolName: currentUser.schoolName,
        avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(teacherName)}&background=8b5cf6&color=fff`
      };
      addUser(newUser);
      alert(`Teacher Added! Login ID: ${newUser.schoolID}`);
    }
    setUsers(getStoredUsers());
    setShowAddTeacher(false);
  };

  const handleRemoveTeacher = (uid: string, name: string) => {
    if (window.confirm(`Are you sure you want to remove Teacher "${name}"?`)) {
      removeUser(uid);
      setUsers(getStoredUsers());
    }
  };

  // Delete handler for Modal
  const handleDeleteFromModal = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (!editingId) return;
    if (window.confirm(`Are you sure you want to remove Teacher "${teacherName}"?`)) {
      removeUser(editingId);
      setUsers(getStoredUsers());
      setShowAddTeacher(false);
    }
  };

  // --- ANNOUNCEMENT LOGIC ---
  const handlePostAnnouncement = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser?.schoolName) {
        alert("Error: You must be assigned to a school to post announcements.");
        return;
    }

    const newAnn: Announcement = {
      id: generateId('ann'),
      title: annTitle,
      content: annContent,
      date: new Date().toISOString().split('T')[0],
      audience: annAudience,
      author: 'Principal',
      schoolName: currentUser.schoolName // Automatically tag with principal's school
    };
    addAnnouncement(newAnn);

    // Refresh local list
    const allAnn = getStoredAnnouncements();
    const relevantAnn = allAnn.filter(a => !a.schoolName || a.schoolName === currentUser.schoolName);
    setAnnouncements(relevantAnn);

    setAnnTitle('');
    setAnnContent('');
    alert('Announcement Posted!');
  };

  const handleDeleteAnnouncement = (id: string) => {
    if(window.confirm('Delete this announcement?')) {
        deleteAnnouncement(id);
        const allAnn = getStoredAnnouncements();
        const relevantAnn = allAnn.filter(a => !a.schoolName || a.schoolName === currentUser?.schoolName);
        setAnnouncements(relevantAnn);
    }
  };

  // Filter teachers by Role AND School
  const myTeachers = users.filter(u => 
      u.role === UserRole.TEACHER && 
      u.schoolName === currentUser?.schoolName
  );

  // Count students in this school for the stats
  const studentsInSchool = users.filter(u => 
      u.role === UserRole.STUDENT &&
      u.schoolName === currentUser?.schoolName
  );

  // --- SUB-PAGES RENDERING ---

  if (currentPage === 'announcements') {
    return (
        <div className="space-y-6">
             <header className="mb-6">
                <h1 className="text-2xl font-bold text-slate-800">Announcements</h1>
                <p className="text-slate-500">Broadcast news to {currentUser?.schoolName || 'your school'}</p>
             </header>

             <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                 {/* Create Form */}
                 <div className="lg:col-span-1">
                     <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                         <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                             <Plus size={20} className="text-blue-600" /> New Announcement
                         </h3>
                         <form onSubmit={handlePostAnnouncement} className="space-y-4">
                             <div>
                                 <label className="block text-sm font-medium text-slate-700 mb-1">Title</label>
                                 <input 
                                     className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                                     placeholder="e.g. Sports Day Update"
                                     value={annTitle}
                                     onChange={e => setAnnTitle(e.target.value)}
                                     required
                                 />
                             </div>
                             <div>
                                 <label className="block text-sm font-medium text-slate-700 mb-1">Audience</label>
                                 <select 
                                     className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                     value={annAudience}
                                     onChange={(e: any) => setAnnAudience(e.target.value)}
                                 >
                                     <option value="all">Everyone</option>
                                     <option value="student">Students Only</option>
                                     <option value="teacher">Teachers Only</option>
                                 </select>
                             </div>
                             <div>
                                 <label className="block text-sm font-medium text-slate-700 mb-1">Message</label>
                                 <textarea 
                                     className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none h-32 resize-none" 
                                     placeholder="Type your message here..."
                                     value={annContent}
                                     onChange={e => setAnnContent(e.target.value)}
                                     required
                                 />
                             </div>
                             <button type="submit" className="w-full py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-medium flex items-center justify-center gap-2">
                                 <Send size={16} /> Post Message
                             </button>
                         </form>
                     </div>
                 </div>

                 {/* List */}
                 <div className="lg:col-span-2">
                     <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                         <div className="p-4 border-b border-slate-100 bg-slate-50">
                             <h3 className="font-bold text-slate-700">Recent Posts</h3>
                         </div>
                         <div className="divide-y divide-slate-100">
                             {announcements.length === 0 ? (
                                 <p className="p-8 text-center text-slate-400">No announcements posted yet.</p>
                             ) : (
                                 announcements.map(ann => (
                                     <div key={ann.id} className="p-6 hover:bg-slate-50 transition-colors">
                                         <div className="flex justify-between items-start mb-2">
                                             <div>
                                                 <h4 className="font-bold text-lg text-slate-800">{ann.title}</h4>
                                                 <div className="flex gap-2 mt-1">
                                                     <span className={`text-xs px-2 py-0.5 rounded-full border ${
                                                         ann.audience === 'all' ? 'bg-purple-50 text-purple-600 border-purple-100' :
                                                         ann.audience === 'teacher' ? 'bg-orange-50 text-orange-600 border-orange-100' :
                                                         'bg-green-50 text-green-600 border-green-100'
                                                     }`}>
                                                         To: {ann.audience.charAt(0).toUpperCase() + ann.audience.slice(1)}
                                                     </span>
                                                     {/* Show Global Badge if no school assigned (from admin) */}
                                                     {!ann.schoolName && (
                                                         <span className="flex items-center gap-1 text-xs px-2 py-0.5 bg-blue-50 text-blue-600 rounded-full border border-blue-100">
                                                             <Globe size={10} /> Global
                                                         </span>
                                                     )}
                                                 </div>
                                             </div>
                                             <div className="flex items-center gap-3">
                                                 <span className="text-sm text-slate-400">{ann.date}</span>
                                                 <button onClick={() => handleDeleteAnnouncement(ann.id)} className="text-red-400 hover:text-red-600">
                                                     <Trash2 size={16} />
                                                 </button>
                                             </div>
                                         </div>
                                         <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{ann.content}</p>
                                     </div>
                                 ))
                             )}
                         </div>
                     </div>
                 </div>
             </div>
        </div>
    );
  }

  if (currentPage === 'settings') {
    return (
      <div className="space-y-6">
        <header className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-2xl font-bold text-slate-800">School Settings</h1>
            <p className="text-slate-500">Staff Management & Configuration</p>
            {currentUser?.schoolName && (
                <span className="text-xs font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded mt-1 inline-block">
                    {currentUser.schoolName}
                </span>
            )}
          </div>
          <button 
            onClick={openAddModal}
            className="flex items-center gap-2 px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors"
          >
            <Plus size={18} /> Add Teacher
          </button>
        </header>

        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
           <div className="p-4 bg-slate-50 border-b border-slate-100">
             <h3 className="font-semibold text-slate-700">Teaching Staff Directory</h3>
           </div>
           <div className="overflow-x-auto">
             <table className="w-full text-left">
              <thead className="text-xs uppercase text-slate-500 border-b border-slate-100">
                <tr>
                  <th className="px-6 py-4">Teacher Name</th>
                  <th className="px-6 py-4">Designation</th>
                  <th className="px-6 py-4">School ID</th>
                  <th className="px-6 py-4">Assigned Class</th>
                  <th className="px-6 py-4">Contact</th>
                  <th className="px-6 py-4 text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {myTeachers.length === 0 ? (
                  <tr><td colSpan={6} className="px-6 py-8 text-center text-slate-400">No teachers found for this school.</td></tr>
                ) : (
                  myTeachers.map(t => (
                    <tr key={t.uid} className="border-b border-slate-50 hover:bg-slate-50/50">
                      <td className="px-6 py-4 flex items-center gap-3">
                        <img src={t.avatarUrl} className="w-8 h-8 rounded-full" />
                        <div>
                          <span className="font-medium text-slate-900 block">{t.name}</span>
                          <span className="text-xs text-slate-400">{t.email}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4 font-semibold text-slate-700 text-sm">
                          {t.designation || <span className="text-slate-400 font-normal italic">Teacher</span>}
                      </td>
                      <td className="px-6 py-4 font-mono text-sm text-slate-600">{t.schoolID}</td>
                      <td className="px-6 py-4 text-sm text-slate-600">{t.assignedClass || '-'}</td>
                      <td className="px-6 py-4 text-sm text-slate-600 font-medium">{t.contactNumber || '-'}</td>
                      <td className="px-6 py-4 text-right">
                          <div className="flex items-center justify-end gap-2">
                            <button 
                                  onClick={() => openEditModal(t)}
                                  className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg transition-colors"
                                  title="Edit Teacher"
                              >
                                  <Pencil size={18} />
                              </button>
                              <button 
                                  onClick={() => handleRemoveTeacher(t.uid, t.name)}
                                  className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                  title="Remove Teacher"
                              >
                                  <Trash2 size={18} />
                              </button>
                          </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
           </div>
        </div>

        {/* Add/Edit Teacher Modal */}
        {showAddTeacher && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
            <div className="bg-white rounded-xl p-8 w-full max-w-md my-8 shadow-2xl relative">
              <h2 className="text-xl font-bold mb-4">{editingId ? 'Edit Teacher' : 'Add New Teacher'}</h2>
              <form onSubmit={handleSaveTeacher} className="space-y-4">
                {formError && <div className="p-2 bg-red-100 text-red-700 rounded text-sm">{formError}</div>}

                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Full Name</label>
                  <input 
                    className="w-full px-4 py-2 border rounded-lg" 
                    placeholder="e.g. John Doe"
                    value={teacherName}
                    onChange={e => setTeacherName(e.target.value)}
                    required 
                  />
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Gender</label>
                        <select
                            className="w-full px-4 py-2 border rounded-lg"
                            value={teacherGender}
                            onChange={e => setTeacherGender(e.target.value)}
                        >
                            <option value="Male">Male</option>
                            <option value="Female">Female</option>
                            <option value="Other">Other</option>
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Designation</label>
                        <input 
                            className="w-full px-4 py-2 border rounded-lg" 
                            placeholder="e.g. H.O.D"
                            value={teacherDesignation}
                            onChange={e => setTeacherDesignation(e.target.value)}
                        />
                    </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">School ID</label>
                  <input 
                    className="w-full px-4 py-2 border rounded-lg font-mono" 
                    placeholder="e.g. TCH-101"
                    value={teacherID}
                    onChange={e => setTeacherID(e.target.value)}
                    required 
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Password</label>
                  <input 
                    className="w-full px-4 py-2 border rounded-lg" 
                    placeholder="Set login password"
                    value={teacherPassword}
                    onChange={e => setTeacherPassword(e.target.value)}
                    required 
                  />
                </div>

                {/* Replaced Class Input with Grade/Section Select */}
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Assign Class (Optional)</label>
                        <select 
                            className="w-full px-4 py-2 border rounded-lg"
                            value={teacherGrade}
                            onChange={e => {
                                setTeacherGrade(e.target.value);
                                setTeacherSection(''); // Reset section
                            }}
                        >
                            <option value="">Select Grade</option>
                            {CLASS_GRADES.map(g => <option key={g} value={g}>{g}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Section/Stream</label>
                        <select 
                            className="w-full px-4 py-2 border rounded-lg"
                            value={teacherSection}
                            onChange={e => setTeacherSection(e.target.value)}
                            disabled={!teacherGrade}
                        >
                            <option value="">Select Section</option>
                            {getSectionOptions(teacherGrade).map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Assign Subject</label>
                        <input 
                            className="w-full px-4 py-2 border rounded-lg" 
                            placeholder="e.g. Math"
                            value={teacherSubject}
                            onChange={e => setTeacherSubject(e.target.value)}
                        />
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">House Team</label>
                        <select
                            className="w-full px-4 py-2 border rounded-lg"
                            value={teacherHouse}
                            onChange={(e) => setTeacherHouse(e.target.value as HouseTeam)}
                        >
                            <option value="">Select House</option>
                            {getHouseOptions().map(h => <option key={h} value={h}>{h}</option>)}
                        </select>
                    </div>
                </div>

                {/* New Contact Fields */}
                <div className="grid grid-cols-2 gap-4">
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Email Address</label>
                        <input 
                            type="email"
                            className="w-full px-4 py-2 border rounded-lg" 
                            placeholder="teacher@school.com"
                            value={teacherEmail}
                            onChange={e => setTeacherEmail(e.target.value)}
                        />
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Contact Number</label>
                        <input 
                            className="w-full px-4 py-2 border rounded-lg" 
                            placeholder="10-digit number"
                            value={teacherContact}
                            onChange={e => setTeacherContact(e.target.value)}
                        />
                    </div>
                </div>

                <div className="flex gap-2 mt-4">
                  {editingId && (
                      <button 
                        type="button"
                        onClick={handleDeleteFromModal}
                        className="px-3 py-2 border border-red-200 text-red-600 rounded-lg hover:bg-red-50 transition-colors"
                        title="Delete Teacher"
                      >
                        <Trash2 size={20} />
                      </button>
                  )}
                  <button type="button" onClick={() => setShowAddTeacher(false)} className="flex-1 py-2 border rounded-lg">Cancel</button>
                  <button type="submit" className="flex-1 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700">{editingId ? 'Update' : 'Add Teacher'}</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  if (currentPage === 'academics') {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-800">Academics Overview</h1>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-white p-6 rounded-xl border border-slate-100 shadow-sm">
                <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
                    <BookOpen className="text-blue-500" /> Curriculum Status
                </h3>
                <p className="text-slate-600">All classes are operating on Schedule A.</p>
                <div className="mt-4 p-4 bg-slate-50 rounded-lg">
                    <div className="flex justify-between text-sm mb-2">
                        <span>Syllabus Completion</span>
                        <span className="font-bold">65%</span>
                    </div>
                    <div className="w-full bg-slate-200 h-2 rounded-full">
                        <div className="bg-blue-500 h-2 rounded-full" style={{ width: '65%' }}></div>
                    </div>
                </div>
            </div>
        </div>
      </div>
    );
  }

  // DEFAULT DASHBOARD VIEW
  return (
    <div className="space-y-6">
      <header className="mb-8">
        <h1 className="text-2xl font-bold text-slate-800">Morning Overview</h1>
        <p className="text-slate-500">Real-time school performance metrics</p>
        {currentUser?.schoolName && (
            <div className="mt-2 inline-flex items-center gap-2 bg-white px-3 py-1.5 rounded-full border border-slate-200 text-sm font-semibold text-blue-600 shadow-sm">
                <BookOpen size={16} /> {currentUser.schoolName}
            </div>
        )}
      </header>

      {/* Top Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <div className="p-3 bg-blue-100 rounded-lg">
              <Users className="text-blue-600 h-6 w-6" />
            </div>
            <span className="text-xs font-semibold px-2 py-1 bg-green-100 text-green-700 rounded-full">
              Live
            </span>
          </div>
          <h3 className="text-slate-500 text-sm font-medium">Total Staff</h3>
          <p className="text-2xl font-bold text-slate-800">{myTeachers.length}</p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <div className="p-3 bg-green-100 rounded-lg">
              <UserCheck className="text-green-600 h-6 w-6" />
            </div>
          </div>
          <h3 className="text-slate-500 text-sm font-medium">Students Enrolled</h3>
          <p className="text-2xl font-bold text-slate-800">{studentsInSchool.length || 'N/A'}</p>
        </div>

        {/* Mock stats for visuals */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <div className="p-3 bg-red-100 rounded-lg">
              <AlertTriangle className="text-red-600 h-6 w-6" />
            </div>
          </div>
          <h3 className="text-slate-500 text-sm font-medium">Absent Staff</h3>
          <p className="text-2xl font-bold text-slate-800">0</p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <div className="p-3 bg-purple-100 rounded-lg">
              <TrendingUp className="text-purple-600 h-6 w-6" />
            </div>
          </div>
          <h3 className="text-slate-500 text-sm font-medium">Avg Performance</h3>
          <p className="text-2xl font-bold text-slate-800">B+</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Attendance Chart */}
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-bold text-slate-800">Weekly Attendance Trends</h3>
          </div>
          <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={WEEKLY_ATTENDANCE}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: '#64748b', fontSize: 12 }} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{ fill: '#64748b', fontSize: 12 }} />
                <Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                <Bar dataKey="present" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40} />
                <Bar dataKey="absent" fill="#ef4444" radius={[4, 4, 0, 0]} barSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Calendar / Events */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="font-bold text-slate-800 mb-4">Upcoming Events</h3>
          <div className="space-y-4">
            {[
              { title: "Staff Meeting", time: "10:00 AM", type: "Academic" },
              { title: "Parent-Teacher Conf", time: "2:00 PM", type: "General" },
            ].map((event, idx) => (
              <div key={idx} className="flex items-start gap-3 pb-3 border-b border-slate-50 last:border-0 last:pb-0">
                <div className="p-2 bg-slate-50 rounded-lg">
                  <Calendar className="text-slate-400 h-5 w-5" />
                </div>
                <div>
                  <h4 className="text-sm font-semibold text-slate-700">{event.title}</h4>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-xs text-slate-500">{event.time}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PrincipalDashboard;

import React, { useState, useEffect } from 'react';
import { StudentRecord, User, UserRole, MarkEntry, Announcement, HouseTeam, SchoolConfig, Assignment } from '../types';
import { getStoredStudents, addStudent, updateStudent, generateId, getStoredUsers, addUser, updateUser, getStoredAnnouncements, saveAllStudents, removeStudent, removeStudent as removeUserFromDb, removeUser, getStoredSchools, getStoredAssignments, addAssignment, deleteAssignment } from '../services/storage';
import { CheckSquare, Square, Save, UserPlus, Pencil, GraduationCap, Plus, Trash2, Megaphone, SortAsc, Calendar, Shield, Flag, User as UserIcon, AlertCircle, Eye, EyeOff, Lock, Globe, School, CheckCircle, XCircle, Calculator, ClipboardList } from 'lucide-react';
import { CLASS_GRADES, SECTIONS_JUNIOR, SECTIONS_SENIOR } from '../constants';

interface Props {
  currentPage?: string;
  currentUser: User;
}

const TeacherDashboard: React.FC<Props> = ({ currentPage = 'dashboard', currentUser }) => {
  const [students, setStudents] = useState<StudentRecord[]>([]);
  const [hasChanges, setHasChanges] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [users, setUsers] = useState<User[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [assignments, setAssignments] = useState<Assignment[]>([]);

  const [currentSchoolConfig, setCurrentSchoolConfig] = useState<SchoolConfig | null>(null);

  // Attendance State
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  // Profile Edit State
  const [editHouseMode, setEditHouseMode] = useState(false);
  const [selectedHouse, setSelectedHouse] = useState<HouseTeam>(currentUser.house || '');

  // Form Error State
  const [formError, setFormError] = useState('');

  // Student Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [name, setName] = useState('');
  const [age, setAge] = useState('');
  const [dob, setDob] = useState('');
  const [gender, setGender] = useState('Male'); 
  const [schoolID, setSchoolID] = useState('');
  const [password, setPassword] = useState(''); 

  // Split Class State
  const [grade, setGrade] = useState('');
  const [section, setSection] = useState('');

  const [email, setEmail] = useState('');
  const [fatherContact, setFatherContact] = useState('');
  const [motherContact, setMotherContact] = useState('');
  const [house, setHouse] = useState<HouseTeam>('');
  const [studentPost, setStudentPost] = useState('');

  // Marks Form State
  const [showMarksModal, setShowMarksModal] = useState(false);
  const [currentMarksStudent, setCurrentMarksStudent] = useState<StudentRecord | null>(null);
  const [marksList, setMarksList] = useState<MarkEntry[]>([]);
  const [newSubject, setNewSubject] = useState('');
  const [newMidTerm, setNewMidTerm] = useState('');
  const [newFinal, setNewFinal] = useState('');

  // Assignment Form State
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [assignTitle, setAssignTitle] = useState('');
  const [assignSubject, setAssignSubject] = useState('');
  const [assignContent, setAssignContent] = useState('');
  const [assignDueDate, setAssignDueDate] = useState('');
  const [assignGrade, setAssignGrade] = useState('');
  const [assignSection, setAssignSection] = useState('');

  useEffect(() => {
    // Load students and sort by roll number initially for display consistency
    const loadedStudents = getStoredStudents();

    // FILTER: Only show students in the Teacher's School AND Assigned Class
    // Strict visibility check per requirement
    const schoolStudents = loadedStudents.filter(s => 
        s.schoolName === currentUser.schoolName && 
        s.className === currentUser.assignedClass
    );

    const sortedStudents = schoolStudents.sort((a, b) => a.rollNumber - b.rollNumber);
    setStudents(sortedStudents);

    setUsers(getStoredUsers());

    // Fetch and filter announcements
    const allAnn = getStoredAnnouncements();
    const relevantAnn = allAnn.filter(a => 
        // Audience filter
        (a.audience === 'all' || a.audience === 'teacher') && 
        // School Filter: Global (no schoolName) OR Matches User's School
        (!a.schoolName || a.schoolName === currentUser.schoolName)
    );
    setAnnouncements(relevantAnn);

    // Fetch Assignments
    refreshAssignments();

    // Fetch School Config
    if (currentUser.schoolName) {
        const schools = getStoredSchools();
        const mySchool = schools.find(s => s.name === currentUser.schoolName);
        if (mySchool) setCurrentSchoolConfig(mySchool.config);
    }
  }, [currentUser]);

  const refreshAssignments = () => {
      const allAssign = getStoredAssignments();
      // Only show assignments from this school created by this teacher
      const myAssign = allAssign.filter(a => 
          a.schoolName === currentUser.schoolName && 
          a.teacherUid === currentUser.uid
      );
      setAssignments(myAssign);
  };

  const refreshStudentList = () => {
    const freshStudents = getStoredStudents();
    const schoolStudents = freshStudents.filter(s => 
        s.schoolName === currentUser.schoolName &&
        s.className === currentUser.assignedClass
    );
    setStudents(schoolStudents.sort((a, b) => a.rollNumber - b.rollNumber));
  };

  // Helper logic for class splitting
  const parseClassString = (classStr: string) => {
    if (!classStr) return { pGrade: '', pSection: '' };
    const parts = classStr.split('-');
    if (parts.length >= 2) {
        return { pGrade: parts[0], pSection: parts.slice(1).join('-') };
    }
    return { pGrade: classStr, pSection: '' };
  };

  const getSectionOptions = (grade: string) => {
      if (['11th', '12th'].includes(grade)) {
          if (currentSchoolConfig && currentSchoolConfig.streams.length > 0) {
              return currentSchoolConfig.streams;
          }
          return SECTIONS_SENIOR;
      }
      return SECTIONS_JUNIOR;
  };

  const getHouseOptions = () => {
      if (currentSchoolConfig && currentSchoolConfig.houseNames.length > 0) {
          return currentSchoolConfig.houseNames;
      }
      return ['Green', 'Blue', 'Yellow', 'Red'];
  };

  const calculateAge = (dobString: string): string => {
    if (!dobString) return '';
    const birthDate = new Date(dobString);
    const today = new Date();
    let calculatedAge = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      calculatedAge--;
    }
    return calculatedAge.toString();
  };

  const handleDobChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newDob = e.target.value;
    setDob(newDob);
    const calculatedAge = calculateAge(newDob);
    setAge(calculatedAge);
  };

  // --- ATTENDANCE LOGIC ---

  const getStudentAttendanceForDate = (student: StudentRecord, date: string): boolean | undefined => {
      if (!student.attendanceHistory) return undefined;
      return student.attendanceHistory[date];
  }

  const handleAttendanceChange = (studentId: string, status: boolean) => {
    setStudents(prev => prev.map(s => {
      if (s.id === studentId) {
        const newHistory = { ...(s.attendanceHistory || {}) };
        newHistory[selectedDate] = status;

        // Update 'attendanceToday' mainly for legacy Principal view compatibility if date is today
        const isToday = selectedDate === new Date().toISOString().split('T')[0];
        const newAttendanceToday = isToday ? status : s.attendanceToday;

        return { ...s, attendanceHistory: newHistory, attendanceToday: newAttendanceToday };
      }
      return s;
    }));
    setHasChanges(true);
  };

  const markAllForDate = (status: boolean) => {
    setStudents(prev => prev.map(s => {
        // Only mark if it's their class teacher or admin
        if (s.className !== currentUser.assignedClass) return s;

        const newHistory = { ...(s.attendanceHistory || {}) };
        newHistory[selectedDate] = status;

        const isToday = selectedDate === new Date().toISOString().split('T')[0];
        const newAttendanceToday = isToday ? status : s.attendanceToday;

        return { ...s, attendanceHistory: newHistory, attendanceToday: newAttendanceToday };
    }));
    setHasChanges(true);
  };

  const saveAttendance = () => {
    students.forEach(s => updateStudent(s));
    setHasChanges(false);
    alert(`Attendance for ${selectedDate} saved!`);
  };

  const getAttendanceStats = (student: StudentRecord) => {
      const history = student.attendanceHistory || {};
      const dates = Object.keys(history);
      const totalWorking = dates.length;
      const totalPresent = dates.filter(d => history[d] === true).length;
      const percentage = totalWorking > 0 ? ((totalPresent / totalWorking) * 100).toFixed(1) : '0.0';
      return { totalWorking, totalPresent, percentage };
  };

  const updateOwnHouse = () => {
      const updatedUser = { ...currentUser, house: selectedHouse };
      updateUser(updatedUser);
      setEditHouseMode(false);
      alert("House updated successfully. Please re-login to see changes in sidebar.");
  };

  // --- STUDENT MODAL LOGIC ---

  const openAddModal = () => {
    if (!currentUser.schoolName) {
        alert("Error: You are not assigned to a school. Cannot add students.");
        return;
    }
    setEditingId(null);
    setFormError('');
    setName('');
    setAge('');
    setDob('');
    setGender('Male');
    setSchoolID('');
    setPassword('');

    // Default class logic if user has a class assigned, parse it, else defaults
    if (currentUser.assignedClass) {
        const { pGrade, pSection } = parseClassString(currentUser.assignedClass);
        setGrade(pGrade);
        setSection(pSection);
    } else {
        setGrade('10th');
        setSection('A');
    }

    setEmail('');
    setFatherContact('');
    setMotherContact('');
    setHouse('');
    setStudentPost('');
    setShowModal(true);
  };

  const openEditModal = (student: StudentRecord) => {
    if (student.className !== currentUser.assignedClass) {
        alert(`You can only edit students in your assigned class (${currentUser.assignedClass || 'None'}).`);
        return;
    }

    setEditingId(student.id);
    setFormError('');
    const userLogin = users.find(u => u.schoolID === student.schoolID);

    setName(student.name);
    setAge(student.age?.toString() || '');
    setDob(student.dob || '');
    setGender(student.gender || 'Male');
    setSchoolID(student.schoolID);
    setPassword(userLogin?.password || '');

    const { pGrade, pSection } = parseClassString(student.className);
    setGrade(pGrade);
    setSection(pSection);

    setEmail(student.email || '');
    setFatherContact(student.fatherContact || '');
    setMotherContact(student.motherContact || '');
    setHouse(student.house || '');
    setStudentPost(student.studentPost || '');
    setShowModal(true);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');

    if (!grade || !section) {
        setFormError("Please select both Class Grade and Section.");
        return;
    }
    const fullClass = `${grade}-${section}`;

    // --- VALIDATION START ---
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (email && !emailRegex.test(email)) {
        setFormError("Please enter a valid school email address (e.g., student@school.edu).");
        return;
    }

    const phoneRegex = /^\d{10}$/;
    if (fatherContact && !phoneRegex.test(fatherContact)) {
        setFormError("Father's contact number must be exactly 10 digits.");
        return;
    }
    if (motherContact && !phoneRegex.test(motherContact)) {
        setFormError("Mother's contact number must be exactly 10 digits.");
        return;
    }

    const isDuplicate = users.some(u => {
        if (editingId) {
             const originalStudent = students.find(s => s.id === editingId);
             if (originalStudent && u.schoolID === originalStudent.schoolID) {
                 return false; 
             }
        }
        return u.schoolID === schoolID;
    });

    if (isDuplicate) {
        setFormError("School ID already exists. Please use a unique ID.");
        return;
    }

    let updatedList = [...getStoredStudents()];

    if (editingId) {
      const existingIndex = updatedList.findIndex(s => s.id === editingId);
      if (existingIndex === -1) return;

      const existingStudent = updatedList[existingIndex];

      const updatedRecord: StudentRecord = {
        ...existingStudent,
        name, schoolID, className: fullClass, age: parseInt(age), dob, gender,
        email, fatherContact, motherContact, house, studentPost,
        schoolName: currentUser.schoolName
      };

      updateStudent(updatedRecord);

      const associatedUser = users.find(u => u.schoolID === existingStudent.schoolID);
      if (associatedUser) {
        const updatedUser: User = {
          ...associatedUser, name, schoolID, password, className: fullClass, gender, dob, email: email, schoolName: currentUser.schoolName
        };
        updateUser(updatedUser);
      }

      alert(`Student ${name} updated successfully.`);

    } else {
      const newRecord: StudentRecord = {
        id: generateId('s'), name, schoolID, rollNumber: 0, attendanceToday: null, attendanceHistory: {}, gradeAverage: 0, className: fullClass,
        age: parseInt(age), dob, gender, email, fatherContact, motherContact, marks: [], house, studentPost,
        schoolName: currentUser.schoolName
      };

      addStudent(newRecord);

      const newUser: User = {
        uid: generateId('u'), name, schoolID, role: UserRole.STUDENT, className: fullClass, password, gender, dob,
        avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=f59e0b&color=fff`,
        schoolName: currentUser.schoolName
      };

      addUser(newUser);
      alert(`Student Added! Login ID: ${schoolID}, Password: ${password}`);
    }

    refreshStudentList();
    setUsers(getStoredUsers());
    setShowModal(false);
  };

  const handleDeleteStudent = (e: React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      if (!editingId) return;

      if (window.confirm("Are you sure you want to remove this student? This will delete all their data including grades.")) {
          // 1. Remove Student Record
          removeStudent(editingId);

          // 2. Remove User Record
          const freshUsers = getStoredUsers();
          const user = freshUsers.find(u => u.schoolID === schoolID); // schoolID is from state
          if (user) {
              removeUser(user.uid);
          }

          // 3. Update UI
          refreshStudentList();
          setUsers(getStoredUsers());
          setShowModal(false);
      }
  };

  // --- MARKS LOGIC ---

  const openMarksModal = (student: StudentRecord) => {
    if (student.className !== currentUser.assignedClass) {
        alert(`You can only manage marks for students in your assigned class (${currentUser.assignedClass || 'None'}).`);
        return;
    }
    setCurrentMarksStudent(student);
    setMarksList(student.marks || []);
    setNewSubject('');
    setNewMidTerm('');
    setNewFinal('');
    setShowMarksModal(true);
  };

  const handleAddMark = () => {
    if (!newSubject || !newMidTerm || !newFinal) {
        alert("Please fill all fields.");
        return;
    }
    const newEntry: MarkEntry = {
        subject: newSubject,
        midTerm: parseFloat(newMidTerm),
        final: parseFloat(newFinal)
    };
    setMarksList([...marksList, newEntry]);
    setNewSubject('');
    setNewMidTerm('');
    setNewFinal('');
  };

  const handleRemoveMark = (index: number) => {
    const updated = [...marksList];
    updated.splice(index, 1);
    setMarksList(updated);
  };

  const saveMarks = () => {
    if (!currentMarksStudent) return;

    let totalScore = 0;
    let count = 0;
    marksList.forEach(m => {
        totalScore += (m.midTerm + m.final) / 2;
        count++;
    });
    const newAverage = count > 0 ? parseFloat((totalScore / count).toFixed(1)) : 0;

    const updatedStudent: StudentRecord = {
        ...currentMarksStudent,
        marks: marksList,
        gradeAverage: newAverage
    };

    updateStudent(updatedStudent);
    refreshStudentList();
    setShowMarksModal(false);
    alert(`Marks updated for ${currentMarksStudent.name}`);
  };

  // --- ASSIGNMENT LOGIC ---
  const openAssignModal = () => {
      if (!currentUser.schoolName) {
          alert("Error: You must be assigned to a school to post assignments.");
          return;
      }
      setAssignTitle('');
      setAssignSubject(currentUser.assignedSubject || '');
      setAssignContent('');
      setAssignDueDate('');
      setAssignGrade('');
      setAssignSection('');
      setShowAssignModal(true);
  };

  const handleSaveAssignment = (e: React.FormEvent) => {
      e.preventDefault();

      if (!assignGrade || !assignSection) {
          alert("Please select target grade and section.");
          return;
      }

      const newAssignment: Assignment = {
          id: generateId('assign'),
          title: assignTitle,
          subject: assignSubject,
          content: assignContent,
          dueDate: assignDueDate,
          targetClass: `${assignGrade}-${assignSection}`,
          schoolName: currentUser.schoolName!,
          authorName: currentUser.name,
          teacherUid: currentUser.uid,
          createdAt: new Date().toISOString()
      };

      addAssignment(newAssignment);
      refreshAssignments();
      setShowAssignModal(false);
      alert('Assignment sent successfully!');
  };

  const handleDeleteAssignment = (id: string) => {
      if(window.confirm('Delete this assignment?')) {
          deleteAssignment(id);
          refreshAssignments();
      }
  };

  const getHouseColor = (house?: HouseTeam) => {
    if (!house) return 'bg-slate-50 text-slate-500 border-slate-100';

    // Check standard colors
    if (house.includes('Green')) return 'bg-green-100 text-green-700 border-green-200';
    if (house.includes('Blue')) return 'bg-blue-100 text-blue-700 border-blue-200';
    if (house.includes('Yellow')) return 'bg-yellow-100 text-yellow-700 border-yellow-200';
    if (house.includes('Red')) return 'bg-red-100 text-red-700 border-red-200';

    return 'bg-indigo-50 text-indigo-700 border-indigo-200';
  };

  // --- RENDERING ---

  // Handle Default Dashboard view for Subject Teachers (No Class Assigned)
  if (currentPage === 'dashboard' && !currentUser.assignedClass) {
      return (
          <div className="text-center p-12">
              <h2 className="text-2xl font-bold text-slate-700 mb-2">Welcome, {currentUser.name}</h2>
              <p className="text-slate-500 mb-8">You are logged in as a Subject Teacher. Please use the tabs to manage assignments and view announcements.</p>
              <button onClick={() => openAssignModal()} className="px-6 py-3 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700">Create Assignment</button>
          </div>
      );
  } else if (currentPage === 'dashboard' && !currentUser.assignedClass) {
       // Fallback logic handled above, but just safe guard
       currentPage = 'assignments';
  }

  if (currentPage === 'profile') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">My Profile</h1>
                 {currentUser.schoolName && <div className="mt-2 inline-flex items-center gap-2 bg-blue-50 px-3 py-1.5 rounded-full border border-blue-100 text-sm font-semibold text-blue-600"><UserIcon size={14} /> {currentUser.schoolName}</div>}
              </header>

              <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden max-w-2xl">
                 <div className="p-8 border-b border-slate-100 flex flex-col md:flex-row items-center gap-6 bg-slate-50">
                    <img src={currentUser.avatarUrl} alt={currentUser.name} className="w-24 h-24 rounded-full bg-blue-100 object-cover border-4 border-white shadow-sm" />
                    <div className="text-center md:text-left"><h2 className="text-2xl font-bold text-slate-900">{currentUser.name}</h2><p className="text-slate-500 font-mono text-sm">{currentUser.schoolID} • {currentUser.designation || 'Teacher'}</p></div>
                 </div>
                 <div className="p-8 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                         <div><label className="block text-xs text-slate-400 font-bold uppercase mb-1">Class Assigned</label><p className="text-lg font-medium text-slate-800">{currentUser.assignedClass || 'N/A'}</p></div>
                         <div><label className="block text-xs text-slate-400 font-bold uppercase mb-1">Subject</label><p className="text-lg font-medium text-slate-800">{currentUser.assignedSubject || 'N/A'}</p></div>
                    </div>
                    <div className="pt-6 border-t border-slate-100">
                         <div className="flex justify-between items-center mb-4"><h3 className="text-sm font-bold text-slate-700 uppercase flex items-center gap-2"><Flag size={16} /> House Team</h3>{!editHouseMode && (<button onClick={() => setEditHouseMode(true)} className="text-xs text-blue-600 hover:text-blue-800 font-medium">Change House</button>)}</div>
                         {editHouseMode ? (
                             <div className="flex items-center gap-3"><select className="flex-1 px-4 py-2 border rounded-lg" value={selectedHouse} onChange={(e) => setSelectedHouse(e.target.value as HouseTeam)}>
                                 <option value="">Select House</option>
                                 {getHouseOptions().map(h => <option key={h} value={h}>{h}</option>)}
                             </select><button onClick={updateOwnHouse} className="px-4 py-2 bg-green-600 text-white rounded-lg">Save</button><button onClick={() => setEditHouseMode(false)} className="px-4 py-2 bg-slate-200 text-slate-600 rounded-lg">Cancel</button></div>
                         ) : (<div className={`inline-flex items-center gap-2 px-4 py-2 rounded-lg border font-bold ${getHouseColor(currentUser.house as HouseTeam)}`}>{currentUser.house || 'No House Assigned'}</div>)}
                    </div>
                 </div>
              </div>
          </div>
      );
  }

  if (currentPage === 'assignments' || (currentPage === 'dashboard' && !currentUser.assignedClass)) {
      return (
          <div className="space-y-6">
              <header className="flex justify-between items-center mb-6">
                  <div>
                      <h1 className="text-2xl font-bold text-slate-800">Assignments</h1>
                      <p className="text-slate-500">Create and manage class assignments</p>
                  </div>
                  <button onClick={openAssignModal} className="flex gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors">
                      <Plus size={18} /> New Assignment
                  </button>
              </header>

              <div className="grid gap-6">
                 {assignments.length === 0 ? (
                     <div className="p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                         <ClipboardList size={48} className="mx-auto mb-4 opacity-20" />
                         <p>No active assignments. Click "New Assignment" to create one.</p>
                     </div>
                 ) : (
                     assignments.map(assign => (
                         <div key={assign.id} className="bg-white rounded-xl p-6 shadow-sm border border-slate-100">
                             <div className="flex justify-between items-start mb-3">
                                 <div>
                                     <h3 className="font-bold text-lg text-slate-800">{assign.title}</h3>
                                     <div className="flex items-center gap-3 mt-1">
                                         <span className="text-xs font-bold text-blue-600 bg-blue-50 px-2 py-0.5 rounded border border-blue-100">{assign.subject}</span>
                                         <span className="text-xs text-slate-500">Target: Class {assign.targetClass}</span>
                                         <span className="text-xs text-slate-400">Due: {assign.dueDate}</span>
                                     </div>
                                 </div>
                                 <button onClick={() => handleDeleteAssignment(assign.id)} className="text-red-400 hover:text-red-600">
                                     <Trash2 size={18} />
                                 </button>
                             </div>
                             <p className="text-slate-600 text-sm whitespace-pre-wrap">{assign.content}</p>
                         </div>
                     ))
                 )}
              </div>

              {/* Create Assignment Modal */}
              {showAssignModal && (
                  <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
                      <div className="bg-white rounded-xl p-8 w-full max-w-lg shadow-2xl relative">
                          <h2 className="text-xl font-bold mb-4">Send Assignment</h2>
                          <form onSubmit={handleSaveAssignment} className="space-y-4">
                              <div>
                                  <label className="block text-sm font-medium mb-1">Title</label>
                                  <input className="w-full p-2 border rounded" value={assignTitle} onChange={e => setAssignTitle(e.target.value)} placeholder="e.g. Chapter 1 Review" required />
                              </div>
                              <div className="grid grid-cols-2 gap-4">
                                   <div>
                                       <label className="block text-sm font-medium mb-1">Subject</label>
                                       <input className="w-full p-2 border rounded" value={assignSubject} onChange={e => setAssignSubject(e.target.value)} required />
                                   </div>
                                   <div>
                                       <label className="block text-sm font-medium mb-1">Due Date</label>
                                       <input type="date" className="w-full p-2 border rounded" value={assignDueDate} onChange={e => setAssignDueDate(e.target.value)} required />
                                   </div>
                              </div>
                              <div className="grid grid-cols-2 gap-4">
                                  <div>
                                      <label className="block text-sm font-medium mb-1">Target Grade</label>
                                      <select className="w-full p-2 border rounded" value={assignGrade} onChange={e => {setAssignGrade(e.target.value); setAssignSection('');}}>
                                          <option value="">Select Grade</option>
                                          {CLASS_GRADES.map(g => <option key={g} value={g}>{g}</option>)}
                                      </select>
                                  </div>
                                  <div>
                                      <label className="block text-sm font-medium mb-1">Target Section</label>
                                      <select className="w-full p-2 border rounded" value={assignSection} onChange={e => setAssignSection(e.target.value)} disabled={!assignGrade}>
                                          <option value="">Select Section</option>
                                          <option value="All">All Sections</option>
                                          {getSectionOptions(assignGrade).map(s => <option key={s} value={s}>{s}</option>)}
                                      </select>
                                  </div>
                              </div>
                              <div>
                                  <label className="block text-sm font-medium mb-1">Instructions / Content</label>
                                  <textarea className="w-full p-2 border rounded h-32" value={assignContent} onChange={e => setAssignContent(e.target.value)} placeholder="Details about the assignment..." required />
                              </div>
                              <div className="flex gap-2 mt-4">
                                  <button type="button" onClick={() => setShowAssignModal(false)} className="flex-1 px-4 py-2 border rounded">Cancel</button>
                                  <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white rounded">Send to Class</button>
                              </div>
                          </form>
                      </div>
                  </div>
              )}
          </div>
      );
  }

  if (currentPage === 'announcements') {
      return (
          <div className="space-y-6">
              <header className="mb-6"><h1 className="text-2xl font-bold text-slate-800">News & Events</h1><p className="text-slate-500">School-wide announcements and teacher updates.</p></header>
              <div className="grid gap-6">
                 {announcements.length === 0 ? (<div className="p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400"><Megaphone size={48} className="mx-auto mb-4 opacity-20" /><p>No announcements at this time.</p></div>) : (announcements.map(ann => (<div key={ann.id} className="bg-white rounded-xl p-6 shadow-sm border border-slate-100 border-l-4 border-l-blue-500"><div className="flex justify-between items-start mb-3"><div><h3 className="font-bold text-lg text-slate-800">{ann.title}</h3><div className="flex items-center gap-2 mt-1"><span className="text-xs text-slate-400 font-mono">{ann.date} • From {ann.author}</span>{ann.schoolName && <span className="flex items-center gap-1 text-[10px] uppercase font-bold px-2 py-0.5 bg-blue-50 text-blue-600 rounded-full border border-blue-100"><School size={10} /> {ann.schoolName}</span>}</div></div></div><p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{ann.content}</p></div>)))}
              </div>
          </div>
      );
  }

  if (currentPage === 'grades') {
      return (
          <div className="space-y-6">
              <header className="flex justify-between items-center mb-6"><div><h1 className="text-2xl font-bold text-slate-800">Student Grades</h1><p className="text-slate-500">Manage Assessments & Results</p></div></header>
              <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-slate-50 text-slate-500 text-xs uppercase"><tr><th className="px-6 py-4">Student Name</th><th className="px-6 py-4">Roll No</th><th className="px-6 py-4">Overall GPA</th><th className="px-6 py-4 text-right">Actions</th></tr></thead>
                        <tbody className="divide-y divide-slate-100">{students.length === 0 ? (<tr><td colSpan={4} className="px-6 py-8 text-center text-slate-400">No students found.</td></tr>) : (students.map(s => { const canEdit = s.className === currentUser.assignedClass; return (<tr key={s.id} className="hover:bg-slate-50/50"><td className="px-6 py-4 font-medium">{s.name}</td><td className="px-6 py-4 text-slate-600">{s.rollNumber}</td><td className="px-6 py-4 font-bold text-blue-600">{s.gradeAverage > 0 ? `${s.gradeAverage}%` : 'N/A'}</td><td className="px-6 py-4 text-right">{canEdit ? (<button onClick={() => openMarksModal(s)} className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg text-sm font-medium hover:bg-blue-100 flex items-center gap-2 ml-auto"><GraduationCap size={16} /> Manage Marks</button>) : (<span className="text-xs text-slate-400 italic">View Only</span>)}</td></tr>) }))}</tbody>
                    </table>
                </div>
              </div>
              {showMarksModal && currentMarksStudent && (
                  <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
                    <div className="bg-white rounded-xl p-8 w-full max-w-3xl shadow-2xl">
                        <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4"><div><h2 className="text-xl font-bold text-slate-800">Manage Marks</h2><p className="text-slate-500 text-sm">Student: {currentMarksStudent.name}</p></div><button onClick={() => setShowMarksModal(false)} className="text-slate-400 text-2xl">&times;</button></div>
                        <div className="space-y-6">
                            <div className="flex gap-3 items-end bg-slate-50 p-4 rounded-lg border border-slate-200">
                                <div className="flex-1"><label className="block text-xs font-bold text-slate-500 mb-1">Subject</label><input className="w-full px-3 py-2 border rounded-md text-sm" value={newSubject} onChange={e => setNewSubject(e.target.value)} /></div>
                                <div className="w-24"><label className="block text-xs font-bold text-slate-500 mb-1">Mid-Term</label><input type="number" className="w-full px-3 py-2 border rounded-md text-sm" value={newMidTerm} onChange={e => setNewMidTerm(e.target.value)} /></div>
                                <div className="w-24"><label className="block text-xs font-bold text-slate-500 mb-1">Finals</label><input type="number" className="w-full px-3 py-2 border rounded-md text-sm" value={newFinal} onChange={e => setNewFinal(e.target.value)} /></div>
                                <button onClick={handleAddMark} className="px-4 py-2 bg-blue-600 text-white rounded-md text-sm font-medium h-[38px]"><Plus size={16} /> Add</button>
                            </div>
                            <table className="w-full text-left border border-slate-200 rounded-lg overflow-hidden">
                                <thead className="bg-slate-100 text-slate-600 text-xs uppercase"><tr><th className="px-4 py-3">Subject</th><th className="px-4 py-3">Mid</th><th className="px-4 py-3">Final</th><th className="px-4 py-3">Avg</th><th className="px-4 py-3 text-right"></th></tr></thead>
                                <tbody className="divide-y divide-slate-100">{marksList.map((m, idx) => (<tr key={idx}><td className="px-4 py-3 font-medium">{m.subject}</td><td className="px-4 py-3 text-slate-600">{m.midTerm}</td><td className="px-4 py-3 text-slate-600">{m.final}</td><td className="px-4 py-3 font-bold text-blue-600">{((m.midTerm + m.final) / 2).toFixed(1)}</td><td className="px-4 py-3 text-right"><button onClick={() => handleRemoveMark(idx)} className="text-red-500"><Trash2 size={16} /></button></td></tr>))}</tbody>
                            </table>
                        </div>
                        <div className="mt-8 flex justify-end gap-3 pt-4 border-t border-slate-100"><button onClick={() => setShowMarksModal(false)} className="px-4 py-2 text-slate-600 rounded-lg">Cancel</button><button onClick={saveMarks} className="px-6 py-2 bg-green-600 text-white font-medium rounded-lg">Save Grades</button></div>
                    </div>
                  </div>
              )}
          </div>
      );
  }

  // DEFAULT DASHBOARD (Attendance & Roster)
  return (
    <div className="space-y-6">
      <header className="flex flex-col gap-4 mb-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <h1 className="text-2xl font-bold text-slate-800">Class {currentUser.assignedClass || 'Unassigned'}</h1>
              <p className="text-slate-500">Attendance Manager & Student Roster</p>
              {currentUser.schoolName && <div className="mt-2 inline-flex items-center gap-2 bg-blue-50 px-3 py-1.5 rounded-full border border-blue-100 text-sm font-semibold text-blue-600"><UserIcon size={14} /> {currentUser.schoolName}</div>}
            </div>
            <div className="flex items-center gap-3">
               <button onClick={openAddModal} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg shadow-sm hover:bg-indigo-700 transition-colors"><Plus size={18} /> Add Student</button>
            </div>
        </div>

        {/* Attendance Controls Bar */}
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-4 items-center justify-between">
            <div className="flex items-center gap-4 w-full md:w-auto">
                <label className="text-sm font-bold text-slate-600 whitespace-nowrap">Attendance Date:</label>
                <input 
                    type="date" 
                    className="border border-slate-300 rounded-lg px-3 py-1.5 text-sm outline-none focus:ring-2 focus:ring-blue-200"
                    value={selectedDate}
                    onChange={(e) => setSelectedDate(e.target.value)}
                    max={new Date().toISOString().split('T')[0]} // Optional: prevents future dates if desired
                />
            </div>

            <div className="flex items-center gap-2 w-full md:w-auto justify-end">
                <button onClick={() => markAllForDate(true)} className="flex items-center gap-2 px-3 py-1.5 bg-green-50 text-green-700 border border-green-200 rounded-lg text-sm font-medium hover:bg-green-100"><CheckCircle size={16} /> Mark All Present</button>
                <button onClick={() => markAllForDate(false)} className="flex items-center gap-2 px-3 py-1.5 bg-red-50 text-red-700 border border-red-200 rounded-lg text-sm font-medium hover:bg-red-100"><XCircle size={16} /> Mark All Absent</button>
                <div className="h-6 w-px bg-slate-200 mx-2"></div>
                <button onClick={saveAttendance} disabled={!hasChanges} className={`flex items-center gap-2 px-6 py-1.5 font-medium rounded-lg transition-all shadow-sm ${hasChanges ? 'bg-blue-600 text-white hover:bg-blue-700' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}><Save size={18} /> Save</button>
            </div>
        </div>
      </header>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-slate-500 text-xs uppercase font-semibold">
                <tr>
                    <th className="px-6 py-4">Roll</th>
                    <th className="px-6 py-4">Student Name</th>
                    <th className="px-6 py-4 text-center">Status ({selectedDate})</th>
                    <th className="px-6 py-4 text-center">Total Working</th>
                    <th className="px-6 py-4 text-center">Total Present</th>
                    <th className="px-6 py-4 text-center">%</th>
                    <th className="px-6 py-4 text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {students.length === 0 ? (<tr><td colSpan={7} className="px-6 py-8 text-center text-slate-400">No students found. Add students to your roster.</td></tr>) : (students.map((student) => {
                    const status = getStudentAttendanceForDate(student, selectedDate);
                    const isPresent = status === true;
                    const isAbsent = status === false;
                    const stats = getAttendanceStats(student);

                    const canEdit = student.className === currentUser.assignedClass;

                    return (
                    <tr key={student.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-6 py-4 font-mono text-sm text-slate-500">{student.rollNumber}</td>
                        <td className="px-6 py-4">
                            <div className="font-medium text-slate-900">{student.name}</div>
                            <div className="text-xs text-slate-400 font-mono">{student.schoolID}</div>
                        </td>

                        {/* Attendance Toggle for Selected Date */}
                        <td className="px-6 py-4">
                            <div className="flex justify-center gap-2">
                                <button 
                                    onClick={() => canEdit && handleAttendanceChange(student.id, true)} 
                                    className={`p-2 rounded-lg transition-all border ${isPresent ? 'bg-green-500 text-white border-green-600 shadow-sm' : 'bg-slate-50 text-slate-300 border-slate-200 hover:border-green-300'}`}
                                    title="Present"
                                    disabled={!canEdit}
                                >
                                    <CheckSquare size={18} />
                                </button>
                                <button 
                                    onClick={() => canEdit && handleAttendanceChange(student.id, false)} 
                                    className={`p-2 rounded-lg transition-all border ${isAbsent ? 'bg-red-500 text-white border-red-600 shadow-sm' : 'bg-slate-50 text-slate-300 border-slate-200 hover:border-red-300'}`}
                                    title="Absent"
                                    disabled={!canEdit}
                                >
                                    <Square size={18} className={isAbsent ? "fill-current" : ""} />
                                </button>
                            </div>
                        </td>

                        {/* Stats Columns */}
                        <td className="px-6 py-4 text-center font-medium text-slate-600">{stats.totalWorking}</td>
                        <td className="px-6 py-4 text-center font-medium text-green-600">{stats.totalPresent}</td>
                        <td className="px-6 py-4 text-center">
                            <span className={`px-2 py-1 rounded-full text-xs font-bold ${parseFloat(stats.percentage) < 75 ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'}`}>
                                {stats.percentage}%
                            </span>
                        </td>

                        <td className="px-6 py-4 text-right">
                            <div className="flex items-center justify-end gap-2">
                                {canEdit ? (
                                    <button onClick={() => openEditModal(student)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg">
                                        <Pencil size={18} />
                                    </button>
                                ) : (
                                    <span className="text-xs text-slate-400 italic flex items-center gap-1"><Lock size={12} /> View Only</span>
                                )}
                            </div>
                        </td>
                    </tr>
                    );
                }))}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
          <div className="bg-white rounded-xl p-8 w-full max-w-lg shadow-2xl relative">
            <h2 className="text-xl font-bold mb-4">{editingId ? 'Edit Student' : 'Add Student'}</h2>
            <form onSubmit={handleSaveStudent} className="space-y-4">
               {formError && <div className="p-2 bg-red-100 text-red-700 rounded">{formError}</div>}
               <div><label className="block text-sm font-medium mb-1">Full Name</label><input className="w-full p-2 border rounded" value={name} onChange={e => setName(e.target.value)} required /></div>
               <div className="grid grid-cols-2 gap-4">
                   <div>
                        <label className="block text-sm font-medium mb-1">Grade</label>
                        <select 
                            className={`w-full p-2 border rounded ${currentUser.assignedClass ? 'bg-slate-100 text-slate-500 cursor-not-allowed' : ''}`}
                            value={grade} 
                            onChange={e => {setGrade(e.target.value); setSection('');}}
                            disabled={!!currentUser.assignedClass} // Disable if assigned class exists
                        >
                            <option value="">Select</option>
                            {CLASS_GRADES.map(g => <option key={g} value={g}>{g}</option>)}
                        </select>
                   </div>
                   <div>
                        <label className="block text-sm font-medium mb-1">Section</label>
                        <select 
                            className={`w-full p-2 border rounded ${currentUser.assignedClass ? 'bg-slate-100 text-slate-500 cursor-not-allowed' : ''}`}
                            value={section} 
                            onChange={e => setSection(e.target.value)} 
                            disabled={!!currentUser.assignedClass || !grade} // Disable if assigned class exists
                        >
                            <option value="">Select</option>
                            {getSectionOptions(grade).map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                   </div>
               </div>

               {/* EXTENDED STUDENT FIELDS START */}
               <div className="grid grid-cols-2 gap-4">
                   <div>
                       <label className="block text-sm font-medium mb-1">Gender</label>
                       <select className="w-full p-2 border rounded" value={gender} onChange={e => setGender(e.target.value)}>
                           <option value="Male">Male</option>
                           <option value="Female">Female</option>
                           <option value="Other">Other</option>
                       </select>
                   </div>
                   <div>
                       <label className="block text-sm font-medium mb-1">House Team</label>
                       <select className="w-full p-2 border rounded" value={house} onChange={e => setHouse(e.target.value as HouseTeam)}>
                           <option value="">Select House</option>
                           {getHouseOptions().map(h => <option key={h} value={h}>{h}</option>)}
                       </select>
                   </div>
               </div>

               <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium mb-1">Student Post</label>
                        <input className="w-full p-2 border rounded" placeholder="e.g. Head Boy" value={studentPost} onChange={e => setStudentPost(e.target.value)} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1">Email</label>
                        <input className="w-full p-2 border rounded" type="email" placeholder="student@school.com" value={email} onChange={e => setEmail(e.target.value)} />
                    </div>
               </div>

               <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium mb-1">Father's Contact</label>
                        <input className="w-full p-2 border rounded" placeholder="10 digits" value={fatherContact} onChange={e => setFatherContact(e.target.value)} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1">Mother's Contact</label>
                        <input className="w-full p-2 border rounded" placeholder="10 digits" value={motherContact} onChange={e => setMotherContact(e.target.value)} />
                    </div>
               </div>
               {/* EXTENDED STUDENT FIELDS END */}

               <div className="grid grid-cols-2 gap-4">
                   <input className="w-full p-2 border rounded" type="date" value={dob} onChange={handleDobChange} />
                   <input className="w-full p-2 border rounded" placeholder="Age" value={age} readOnly />
               </div>
               <div><label className="block text-sm font-medium mb-1">School ID</label><input className="w-full p-2 border rounded" value={schoolID} onChange={e => setSchoolID(e.target.value)} required /></div>
               <div><label className="block text-sm font-medium mb-1">Password</label><input className="w-full p-2 border rounded" value={password} onChange={e => setPassword(e.target.value)} required /></div>

               <div className="flex gap-2 mt-4">
                   {editingId && <button type="button" onClick={handleDeleteStudent} className="px-4 py-2 text-red-600 border border-red-200 rounded hover:bg-red-50">Delete</button>}
                   <button type="button" onClick={() => setShowModal(false)} className="flex-1 px-4 py-2 border rounded">Cancel</button>
                   <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white rounded">Save</button>
               </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TeacherDashboard;

import React, { useState, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer 
} from 'recharts';
import { 
  Users, UserCheck, AlertTriangle, TrendingUp, Calendar, Plus, Search, BookOpen, Trash2, Pencil, Megaphone, Send, Globe, School
} from 'lucide-react';
import { WEEKLY_ATTENDANCE, CLASS_GRADES, SECTIONS_JUNIOR, SECTIONS_SENIOR } from '../constants';
import { User, UserRole, Announcement, HouseTeam, School as SchoolType, SchoolConfig } from '../types';
import { getStoredUsers, addUser, updateUser, removeUser, generateId, getStoredAnnouncements, addAnnouncement, deleteAnnouncement, getStoredSchools } from '../services/storage';

interface Props {
  currentPage?: string;
  currentUser?: User; 
}

const PrincipalDashboard: React.FC<Props> = ({ currentPage = 'dashboard' }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentSchoolConfig, setCurrentSchoolConfig] = useState<SchoolConfig | null>(null);

  const [showAddTeacher, setShowAddTeacher] = useState(false);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);

  // Teacher Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [teacherName, setTeacherName] = useState('');
  const [teacherID, setTeacherID] = useState('');
  const [teacherPassword, setTeacherPassword] = useState('');

  // Split Class State
  const [teacherGrade, setTeacherGrade] = useState('');
  const [teacherSection, setTeacherSection] = useState('');

  const [teacherSubject, setTeacherSubject] = useState('');
  const [teacherGender, setTeacherGender] = useState('Male'); 
  const [teacherDesignation, setTeacherDesignation] = useState('');
  const [teacherHouse, setTeacherHouse] = useState<HouseTeam>('');
  const [teacherEmail, setTeacherEmail] = useState('');
  const [teacherContact, setTeacherContact] = useState('');

  // Form Error
  const [formError, setFormError] = useState('');

  // Announcement Form State
  const [annTitle, setAnnTitle] = useState('');
  const [annContent, setAnnContent] = useState('');
  const [annAudience, setAnnAudience] = useState<'all' | 'student' | 'teacher'>('all');

  useEffect(() => {
    setUsers(getStoredUsers());

    // Get current user to know which School we are in
    const stored = localStorage.getItem('nexus_user');
    let userObj: User | null = null;
    if (stored) {
        userObj = JSON.parse(stored);
        setCurrentUser(userObj);

        // Fetch School Config
        if (userObj && userObj.schoolName) {
            const schools = getStoredSchools();
            const mySchool = schools.find(s => s.name === userObj?.schoolName);
            if (mySchool) setCurrentSchoolConfig(mySchool.config);
        }
    }

    const allAnn = getStoredAnnouncements();
    // Filter announcements: Show if Global (no schoolName) OR Matches User's School
    const relevantAnn = allAnn.filter(a => !a.schoolName || (userObj && a.schoolName === userObj.schoolName));
    setAnnouncements(relevantAnn);

  }, []);

  // Helper logic for class splitting
  const parseClassString = (classStr: string) => {
    if (!classStr) return { pGrade: '', pSection: '' };
    const parts = classStr.split('-');
    if (parts.length >= 2) {
        return { pGrade: parts[0], pSection: parts.slice(1).join('-') };
    }
    return { pGrade: classStr, pSection: '' };
  };

  const getSectionOptions = (grade: string) => {
      if (['11th', '12th'].includes(grade)) {
          if (currentSchoolConfig && currentSchoolConfig.streams.length > 0) {
              return currentSchoolConfig.streams;
          }
          return SECTIONS_SENIOR;
      }
      return SECTIONS_JUNIOR;
  };

  const getHouseOptions = () => {
      if (currentSchoolConfig && currentSchoolConfig.houseNames.length > 0) {
          return currentSchoolConfig.houseNames;
      }
      return ['Green', 'Blue', 'Yellow', 'Red'];
  };

  // --- TEACHER LOGIC ---
  const openAddModal = () => {
    setEditingId(null);
    setFormError('');
    setTeacherName('');
    setTeacherID('');
    setTeacherPassword('');
    setTeacherGrade('');
    setTeacherSection('');
    setTeacherSubject('');
    setTeacherGender('Male');
    setTeacherDesignation('');
    setTeacherHouse('');
    setTeacherEmail('');
    setTeacherContact('');
    setShowAddTeacher(true);
  };

  const openEditModal = (user: User) => {
    setEditingId(user.uid);
    setFormError('');
    setTeacherName(user.name);
    setTeacherID(user.schoolID);
    setTeacherPassword(user.password || '');

    const { pGrade, pSection } = parseClassString(user.assignedClass || '');
    setTeacherGrade(pGrade);
    setTeacherSection(pSection);

    setTeacherSubject(user.assignedSubject || '');
    setTeacherGender(user.gender || 'Male');
    setTeacherDesignation(user.designation || '');
    setTeacherHouse(user.house || '');
    setTeacherEmail(user.email || '');
    setTeacherContact(user.contactNumber || '');
    setShowAddTeacher(true);
  };

  const handleSaveTeacher = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError('');

    if (!currentUser?.schoolName) {
        setFormError("Error: You are not assigned to a valid School. Cannot add teachers.");
        return;
    }

    // Duplicate Check
    const isDuplicate = users.some(u => u.schoolID === teacherID && u.uid !== editingId);
    if (isDuplicate) {
        setFormError("School ID already exists. Please use a unique ID.");
        return;
    }

