              <div className="bg-white dark:bg-slate-900 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-xs uppercase"><tr><th className="px-6 py-4">Student Name</th><th className="px-6 py-4">Roll No</th><th className="px-6 py-4">Overall GPA</th><th className="px-6 py-4 text-right">Actions</th></tr></thead>
                        <tbody className="divide-y divide-slate-100 dark:divide-slate-800">{students.length === 0 ? (<tr><td colSpan={4} className="px-6 py-8 text-center text-slate-400">No students found.</td></tr>) : (students.map(s => { const canEdit = s.className === currentUser.assignedClass; return (<tr key={s.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/50"><td className="px-6 py-4 font-medium text-slate-900 dark:text-white">{s.name}</td><td className="px-6 py-4 text-slate-600 dark:text-slate-300">{s.rollNumber}</td><td className="px-6 py-4 font-bold text-blue-600 dark:text-blue-400">{s.gradeAverage > 0 ? `${s.gradeAverage}%` : 'N/A'}</td><td className="px-6 py-4 text-right">{canEdit ? (<button onClick={() => openMarksModal(s)} className="px-3 py-1.5 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-lg text-sm font-medium hover:bg-blue-100 dark:hover:bg-blue-900/50 flex items-center gap-2 ml-auto"><GraduationCap size={16} /> Manage Marks</button>) : (<span className="text-xs text-slate-400 italic">View Only</span>)}</td></tr>) }))}</tbody>
                    </table>
                </div>
              </div>
              {showMarksModal && currentMarksStudent && (
                  <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10 backdrop-blur-sm">
                    <div className="bg-white dark:bg-slate-900 rounded-xl p-8 w-full max-w-3xl shadow-2xl border border-slate-200 dark:border-slate-800">
                        <div className="flex justify-between items-center mb-6 border-b border-slate-100 dark:border-slate-800 pb-4"><div><h2 className="text-xl font-bold text-slate-800 dark:text-white">Manage Marks</h2><p className="text-slate-500 dark:text-slate-400 text-sm">Student: {currentMarksStudent.name}</p></div><button onClick={() => setShowMarksModal(false)} className="text-slate-400 text-2xl hover:text-slate-600 dark:hover:text-slate-300">&times;</button></div>
                        <div className="space-y-6">
                            <div className="flex gap-3 items-end bg-slate-50 dark:bg-slate-800 p-4 rounded-lg border border-slate-200 dark:border-slate-700">
                                <div className="flex-1"><label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Subject</label><input className="w-full px-3 py-2 border dark:border-slate-600 rounded-md text-sm bg-white dark:bg-slate-700 text-slate-900 dark:text-white outline-none" value={newSubject} onChange={e => setNewSubject(e.target.value)} /></div>
                                <div className="w-24"><label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Mid-Term</label><input type="number" className="w-full px-3 py-2 border dark:border-slate-600 rounded-md text-sm bg-white dark:bg-slate-700 text-slate-900 dark:text-white outline-none" value={newMidTerm} onChange={e => setNewMidTerm(e.target.value)} /></div>
                                <div className="w-24"><label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Finals</label><input type="number" className="w-full px-3 py-2 border dark:border-slate-600 rounded-md text-sm bg-white dark:bg-slate-700 text-slate-900 dark:text-white outline-none" value={newFinal} onChange={e => setNewFinal(e.target.value)} /></div>
                                <button onClick={handleAddMark} className="px-4 py-2 bg-blue-600 text-white rounded-md text-sm font-medium h-[38px]"><Plus size={16} /> Add</button>
                            </div>
                            <table className="w-full text-left border border-slate-200 dark:border-slate-700 rounded-lg overflow-hidden">
                                <thead className="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 text-xs uppercase"><tr><th className="px-4 py-3">Subject</th><th className="px-4 py-3">Mid</th><th className="px-4 py-3">Final</th><th className="px-4 py-3">Avg</th><th className="px-4 py-3 text-right"></th></tr></thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">{marksList.map((m, idx) => (<tr key={idx}><td className="px-4 py-3 font-medium text-slate-900 dark:text-white">{m.subject}</td><td className="px-4 py-3 text-slate-600 dark:text-slate-300">{m.midTerm}</td><td className="px-4 py-3 text-slate-600 dark:text-slate-300">{m.final}</td><td className="px-4 py-3 font-bold text-blue-600 dark:text-blue-400">{((m.midTerm + m.final) / 2).toFixed(1)}</td><td className="px-4 py-3 text-right"><button onClick={() => handleRemoveMark(idx)} className="text-red-500 hover:text-red-700 dark:hover:text-red-400"><Trash2 size={16} /></button></td></tr>))}</tbody>
                            </table>
                        </div>
                        <div className="mt-8 flex justify-end gap-3 pt-4 border-t border-slate-100 dark:border-slate-800"><button onClick={() => setShowMarksModal(false)} className="px-4 py-2 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-800">Cancel</button><button onClick={saveMarks} className="px-6 py-2 bg-green-600 text-white font-medium rounded-lg hover:bg-green-700">Save Grades</button></div>
                    </div>
                  </div>
              )}
          </div>
      );
  }

  // DEFAULT DASHBOARD (Attendance & Roster)
  return (
    <div className="space-y-6">
      <header className="flex flex-col gap-4 mb-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <h1 className="text-2xl font-bold text-slate-800 dark:text-white">Class {currentUser.assignedClass || 'Unassigned'}</h1>
              <p className="text-slate-500 dark:text-slate-400">Attendance Manager & Student Roster</p>
              {currentUser.schoolName && <div className="mt-2 inline-flex items-center gap-2 bg-blue-50 dark:bg-blue-900/30 px-3 py-1.5 rounded-full border border-blue-100 dark:border-blue-800 text-sm font-semibold text-blue-600 dark:text-blue-400"><UserIcon size={14} /> {currentUser.schoolName}</div>}
            </div>
            <div className="flex items-center gap-3">
               <button onClick={openAddModal} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg shadow-sm hover:bg-indigo-700 transition-colors"><Plus size={18} /> Add Student</button>
            </div>
        </div>

        {/* Attendance Controls Bar */}
        <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col md:flex-row gap-4 items-center justify-between">
            <div className="flex items-center gap-4 w-full md:w-auto">
                <label className="text-sm font-bold text-slate-600 dark:text-slate-300 whitespace-nowrap">Attendance Date:</label>
                <input 
                    type="date" 
                    className="border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded-lg px-3 py-1.5 text-sm outline-none focus:ring-2 focus:ring-blue-200 dark:focus:ring-blue-900"
                    value={selectedDate}
                    onChange={(e) => setSelectedDate(e.target.value)}
                    max={new Date().toISOString().split('T')[0]} // Optional: prevents future dates if desired
                />
            </div>

            <div className="flex items-center gap-2 w-full md:w-auto justify-end">
                <button onClick={() => markAllForDate(true)} className="flex items-center gap-2 px-3 py-1.5 bg-green-50 dark:bg-green-900/30 text-green-700 dark:text-green-400 border border-green-200 dark:border-green-800 rounded-lg text-sm font-medium hover:bg-green-100 dark:hover:bg-green-900/50"><CheckCircle size={16} /> Mark All Present</button>
                <button onClick={() => markAllForDate(false)} className="flex items-center gap-2 px-3 py-1.5 bg-red-50 dark:bg-red-900/30 text-red-700 dark:text-red-400 border border-red-200 dark:border-red-800 rounded-lg text-sm font-medium hover:bg-red-100 dark:hover:bg-red-900/50"><XCircle size={16} /> Mark All Absent</button>
                <div className="h-6 w-px bg-slate-200 dark:bg-slate-700 mx-2"></div>
                <button onClick={saveAttendance} disabled={!hasChanges} className={`flex items-center gap-2 px-6 py-1.5 font-medium rounded-lg transition-all shadow-sm ${hasChanges ? 'bg-blue-600 text-white hover:bg-blue-700' : 'bg-slate-200 dark:bg-slate-800 text-slate-400 dark:text-slate-500 cursor-not-allowed'}`}><Save size={18} /> Save</button>
            </div>
        </div>
      </header>

      <div className="bg-white dark:bg-slate-900 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-xs uppercase font-semibold">
                <tr>
                    <th className="px-6 py-4">Roll</th>
                    <th className="px-6 py-4">Student Name</th>
                    <th className="px-6 py-4 text-center">Status ({selectedDate})</th>
                    <th className="px-6 py-4 text-center">Total Working</th>
                    <th className="px-6 py-4 text-center">Total Present</th>
                    <th className="px-6 py-4 text-center">%</th>
                    <th className="px-6 py-4 text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {students.length === 0 ? (<tr><td colSpan={7} className="px-6 py-8 text-center text-slate-400">No students found. Add students to your roster.</td></tr>) : (students.map((student) => {
                    const status = getStudentAttendanceForDate(student, selectedDate);
                    const isPresent = status === true;
                    const isAbsent = status === false;
                    const stats = getAttendanceStats(student);

                    const canEdit = student.className === currentUser.assignedClass;

                    return (
                    <tr key={student.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/50 transition-colors">
                        <td className="px-6 py-4 font-mono text-sm text-slate-500 dark:text-slate-400">{student.rollNumber}</td>
                        <td className="px-6 py-4">
                            <div className="font-medium text-slate-900 dark:text-white">{student.name}</div>
                            <div className="text-xs text-slate-400 font-mono">{student.schoolID}</div>
                        </td>

                        {/* Attendance Toggle for Selected Date */}
                        <td className="px-6 py-4">
                            <div className="flex justify-center gap-2">
                                <button 
                                    onClick={() => canEdit && handleAttendanceChange(student.id, true)} 
                                    className={`p-2 rounded-lg transition-all border ${isPresent ? 'bg-green-500 text-white border-green-600 shadow-sm' : 'bg-slate-50 dark:bg-slate-800 text-slate-300 dark:text-slate-600 border-slate-200 dark:border-slate-700 hover:border-green-300 dark:hover:border-green-700'}`}
                                    title="Present"
                                    disabled={!canEdit}
                                >
                                    <CheckSquare size={18} />
                                </button>
                                <button 
                                    onClick={() => canEdit && handleAttendanceChange(student.id, false)} 
                                    className={`p-2 rounded-lg transition-all border ${isAbsent ? 'bg-red-500 text-white border-red-600 shadow-sm' : 'bg-slate-50 dark:bg-slate-800 text-slate-300 dark:text-slate-600 border-slate-200 dark:border-slate-700 hover:border-red-300 dark:hover:border-red-700'}`}
                                    title="Absent"
                                    disabled={!canEdit}
                                >
                                    <Square size={18} className={isAbsent ? "fill-current" : ""} />
                                </button>
                            </div>
                        </td>

                        {/* Stats Columns */}
                        <td className="px-6 py-4 text-center font-medium text-slate-600 dark:text-slate-300">{stats.totalWorking}</td>
                        <td className="px-6 py-4 text-center font-medium text-green-600 dark:text-green-400">{stats.totalPresent}</td>
                        <td className="px-6 py-4 text-center">
                            <span className={`px-2 py-1 rounded-full text-xs font-bold ${parseFloat(stats.percentage) < 75 ? 'bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400' : 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400'}`}>
                                {stats.percentage}%
                            </span>
                        </td>

                        <td className="px-6 py-4 text-right">
                            <div className="flex items-center justify-end gap-2">
                                {canEdit ? (
                                    <button onClick={() => openEditModal(student)} className="p-2 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-lg">
                                        <Pencil size={18} />
                                    </button>
                                ) : (
                                    <span className="text-xs text-slate-400 italic flex items-center gap-1"><Lock size={12} /> View Only</span>
                                )}
                            </div>
                        </td>
                    </tr>
                    );
                }))}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10 backdrop-blur-sm">
          <div className="bg-white dark:bg-slate-900 rounded-xl p-8 w-full max-w-lg shadow-2xl relative border border-slate-200 dark:border-slate-800">
            <h2 className="text-xl font-bold mb-4 text-slate-900 dark:text-white">{editingId ? 'Edit Student' : 'Add Student'}</h2>
            <form onSubmit={handleSaveStudent} className="space-y-4">
               {formError && <div className="p-2 bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400 rounded">{formError}</div>}
               <div><label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">Full Name</label><input className="w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded" value={name} onChange={e => setName(e.target.value)} required /></div>
               <div className="grid grid-cols-2 gap-4">
                   <div>
                        <label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">Grade</label>
                        <select 
                            className={`w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded ${currentUser.assignedClass ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 cursor-not-allowed' : ''}`}
                            value={grade} 
                            onChange={e => {setGrade(e.target.value); setSection('');}}
                            disabled={!!currentUser.assignedClass} // Disable if assigned class exists
                        >
                            <option value="">Select</option>
                            {CLASS_GRADES.map(g => <option key={g} value={g}>{g}</option>)}
                        </select>
                   </div>
                   <div>
                        <label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">Section</label>
                        <select 
                            className={`w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded ${currentUser.assignedClass ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 cursor-not-allowed' : ''}`}
                            value={section} 
                            onChange={e => setSection(e.target.value)} 
                            disabled={!!currentUser.assignedClass || !grade} // Disable if assigned class exists
                        >
                            <option value="">Select</option>
                            {getSectionOptions(grade).map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                   </div>
               </div>

               {/* EXTENDED STUDENT FIELDS START */}
               <div className="grid grid-cols-2 gap-4">
                   <div>
                       <label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">Gender</label>
                       <select className="w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded" value={gender} onChange={e => setGender(e.target.value)}>
                           <option value="Male">Male</option>
                           <option value="Female">Female</option>
                           <option value="Other">Other</option>
                       </select>
                   </div>
                   <div>
                       <label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">House Team</label>
                       <select className="w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded" value={house} onChange={e => setHouse(e.target.value as HouseTeam)}>
                           <option value="">Select House</option>
                           {getHouseOptions().map(h => <option key={h} value={h}>{h}</option>)}
                       </select>
                   </div>
               </div>

               <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">Student Post</label>
                        <input className="w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded" placeholder="e.g. Head Boy" value={studentPost} onChange={e => setStudentPost(e.target.value)} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">Email</label>
                        <input className="w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded" type="email" placeholder="student@school.com" value={email} onChange={e => setEmail(e.target.value)} />
                    </div>
               </div>

               <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">Father's Contact</label>
                        <input className="w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded" placeholder="10 digits" value={fatherContact} onChange={e => setFatherContact(e.target.value)} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">Mother's Contact</label>
                        <input className="w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded" placeholder="10 digits" value={motherContact} onChange={e => setMotherContact(e.target.value)} />
                    </div>
               </div>
               {/* EXTENDED STUDENT FIELDS END */}

               <div className="grid grid-cols-2 gap-4">
                   <input className="w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded" type="date" value={dob} onChange={handleDobChange} />
                   <input className="w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded" placeholder="Age" value={age} readOnly />
               </div>
               <div><label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">School ID</label><input className="w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded" value={schoolID} onChange={e => setSchoolID(e.target.value)} required /></div>
               <div><label className="block text-sm font-medium mb-1 text-slate-700 dark:text-slate-300">Password</label><input className="w-full p-2 border dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white rounded" value={password} onChange={e => setPassword(e.target.value)} required /></div>

               <div className="flex gap-2 mt-4">
                   {editingId && <button type="button" onClick={handleDeleteStudent} className="px-4 py-2 text-red-600 border border-red-200 dark:border-red-800 rounded hover:bg-red-50 dark:hover:bg-red-900/30">Delete</button>}
                   <button type="button" onClick={() => setShowModal(false)} className="flex-1 px-4 py-2 border dark:border-slate-700 text-slate-700 dark:text-slate-300 rounded">Cancel</button>
                   <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white rounded">Save</button>
               </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TeacherDashboard;

import React, { useState, useEffect } from 'react';
import { User, StudentRecord, MarkEntry, Announcement, HouseTeam, UserRole, Assignment } from '../types';
import { Book, Award, Clock, GraduationCap, Phone, Mail, User as UserIcon, Hash, Megaphone, Calendar, Shield, Flag, Globe, School, ClipboardList } from 'lucide-react';
import { getStoredStudents, getStoredAnnouncements, getStoredUsers, getStoredAssignments } from '../services/storage';

interface StudentDashboardProps {
  user: User;
  currentPage?: string;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ user, currentPage = 'dashboard' }) => {
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [assignments, setAssignments] = useState<Assignment[]>([]);

  useEffect(() => {
     // Fetch Announcements
     const allAnn = getStoredAnnouncements();
     const relevantAnn = allAnn.filter(a => 
         // Audience Filter
         (a.audience === 'all' || a.audience === 'student') &&
         // School Filter: Global (no schoolName) OR Matches User's School
         (!a.schoolName || a.schoolName === user.schoolName)
     );
     setAnnouncements(relevantAnn);

     // Fetch Assignments
     if (user.className && user.schoolName) {
         const allAssign = getStoredAssignments();
         const relevantAssign = allAssign.filter(a => 
             a.schoolName === user.schoolName && 
             a.targetClass === user.className
         );
         setAssignments(relevantAssign);
     }

  }, [user]);

  const getStudentProfile = (): StudentRecord | undefined => {
    return getStoredStudents().find(s => s.schoolID === user.schoolID);
  };

  const calculateGrade = (score: number) => {
    if (score >= 90) return 'A';
    if (score >= 85) return 'B+';
    if (score >= 80) return 'B';
    if (score >= 75) return 'C+';
    if (score >= 70) return 'C';
    if (score >= 60) return 'D';
    return 'F';
  };

   const getHouseColor = (house?: HouseTeam) => {
    if (!house) return 'text-slate-600 dark:text-slate-300 bg-slate-50 dark:bg-slate-800';

    if (house.includes('Green')) return 'text-green-600 dark:text-green-400 bg-green-50 dark:bg-green-900/30 border-green-200 dark:border-green-800';
    if (house.includes('Blue')) return 'text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/30 border-blue-200 dark:border-blue-800';
    if (house.includes('Yellow')) return 'text-yellow-600 dark:text-yellow-400 bg-yellow-50 dark:bg-yellow-900/30 border-yellow-200 dark:border-yellow-800';
    if (house.includes('Red')) return 'text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/30 border-red-200 dark:border-red-800';

    return 'text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-900/30 border-indigo-200 dark:border-indigo-800';
  };

  if (currentPage === 'teachers') {
      const studentProfile = getStudentProfile();
      const allUsers = getStoredUsers();

      // Filter teachers: Must match Role, School, and Class.
      const myTeachers = allUsers.filter(u => 
          u.role === UserRole.TEACHER && 
          u.schoolName === user.schoolName && // Ensure same school
          (u.assignedClass === studentProfile?.className)
      );

      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800 dark:text-white">My Teachers</h1>
                 <p className="text-slate-500 dark:text-slate-400">Faculty directory for Class {studentProfile?.className || 'N/A'} at {user.schoolName}</p>
              </header>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {myTeachers.length === 0 ? (
                      <div className="col-span-full p-12 text-center bg-white dark:bg-slate-900 rounded-xl border border-slate-100 dark:border-slate-800 text-slate-400">
                           <UserIcon size={48} className="mx-auto mb-4 opacity-20" />
                           <p>No specific class teachers found for your school.</p>
                      </div>
                  ) : (
                      myTeachers.map(teacher => (
                          <div key={teacher.uid} className="bg-white dark:bg-slate-900 rounded-xl border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden hover:shadow-md transition-shadow">
                              <div className="p-6 flex flex-col items-center text-center border-b border-slate-50 dark:border-slate-800">
                                  <img 
                                      src={teacher.avatarUrl} 
                                      alt={teacher.name} 
                                      className="w-20 h-20 rounded-full bg-slate-100 dark:bg-slate-800 object-cover mb-4 border-4 border-white dark:border-slate-700 shadow-sm"
                                  />
                                  <h3 className="font-bold text-lg text-slate-800 dark:text-white">{teacher.name}</h3>
                                  <p className="text-blue-600 dark:text-blue-400 font-medium text-sm">{teacher.assignedSubject || 'Teacher'}</p>
                                  <p className="text-slate-400 text-xs mt-1">{teacher.designation}</p>
                              </div>
                              <div className="p-4 bg-slate-50 dark:bg-slate-800 space-y-3">
                                  <div className="flex items-center gap-3 text-sm">
                                      <div className="p-2 bg-white dark:bg-slate-700 rounded-lg text-slate-400 shadow-sm">
                                          <Mail size={16} />
                                      </div>
                                      <div className="overflow-hidden">
                                          <p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Email</p>
                                          <p className="text-slate-700 dark:text-slate-300 truncate" title={teacher.email || 'N/A'}>
                                              {teacher.email || <span className="text-slate-400 italic">Not Available</span>}
                                          </p>
                                      </div>
                                  </div>
                                  <div className="flex items-center gap-3 text-sm">
                                      <div className="p-2 bg-white dark:bg-slate-700 rounded-lg text-slate-400 shadow-sm">
                                          <Phone size={16} />
                                      </div>
                                      <div>
                                          <p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase">Contact</p>
                                          <p className="text-slate-700 dark:text-slate-300">
                                              {teacher.contactNumber || <span className="text-slate-400 italic">Not Available</span>}
                                          </p>
                                      </div>
                                  </div>
                              </div>
                          </div>
                      ))
                  )}
              </div>
          </div>
      );
  }

  if (currentPage === 'profile') {
