                {/* Header Section */}
                <div className="bg-slate-50 dark:bg-slate-800 p-8 border-b border-slate-100 dark:border-slate-700 flex flex-col md:flex-row items-center gap-6">
                    <img 
                        src={user.avatarUrl} 
                        alt={studentProfile.name} 
                        className="w-24 h-24 rounded-full bg-blue-100 dark:bg-blue-900 object-cover border-4 border-white dark:border-slate-700 shadow-sm"
                    />
                    <div className="text-center md:text-left space-y-1">
                        <h2 className="text-2xl font-bold text-slate-900 dark:text-white">{studentProfile.name}</h2>
                        <div className="flex flex-wrap justify-center md:justify-start gap-2 text-slate-500 dark:text-slate-400 font-mono text-sm">
                            <span className="px-3 py-1 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-full text-slate-700 dark:text-slate-300 flex items-center gap-1">
                                <Hash size={14} /> {studentProfile.schoolID}
