                    </div>

                    {/* Personal Info */}
                    <div className="space-y-6">
                        <h3 className="text-xs font-bold text-blue-600 dark:text-blue-400 uppercase tracking-widest border-b border-blue-100 dark:border-blue-900 pb-2">Personal Details</h3>
                        <div className="grid grid-cols-1 gap-4">
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Age & Gender</label>
