            <div className="bg-white dark:bg-slate-900 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-xs uppercase">
                        <tr>
                            <th className="px-6 py-4">Subject</th>
                            <th className="px-6 py-4">Mid-Term</th>
                            <th className="px-6 py-4">Finals</th>
                            <th className="px-6 py-4">Avg Score</th>
                            <th className="px-6 py-4">Grade</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                        {marks.length === 0 ? (
                            <tr><td colSpan={5} className="p-8 text-center text-slate-400">No grades available yet.</td></tr>
                        ) : (
                            marks.map((m, i) => {
                                const avg = (m.midTerm + m.final) / 2;
                                return (
                                    <tr key={i}>
                                        <td className="px-6 py-4 font-medium text-slate-900 dark:text-white">{m.subject}</td>
                                        <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{m.midTerm}</td>
                                        <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{m.final}</td>
                                        <td className="px-6 py-4 font-bold text-slate-800 dark:text-slate-200">{avg.toFixed(1)}</td>
                                        <td className={`px-6 py-4 font-bold ${avg >= 70 ? 'text-green-600 dark:text-green-400' : 'text-red-500 dark:text-red-400'}`}>
                                            {calculateGrade(avg)}
                                        </td>
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>

            {studentProfile && studentProfile.gradeAverage > 0 && (
                <div className="p-4 bg-blue-50 dark:bg-blue-900/30 border border-blue-100 dark:border-blue-800 rounded-lg text-sm text-blue-700 dark:text-blue-300 flex justify-between items-center">
                    <span>Cumulative Grade Average</span>
                    <span className="font-bold text-lg">{studentProfile.gradeAverage}%</span>
                </div>
            )}
        </div>
    )
  }

  return (
    <div className="space-y-6">
      <header className="bg-gradient-to-r from-blue-600 to-indigo-700 rounded-2xl p-8 text-white shadow-lg">
        <div className="flex items-center gap-6">
          <img 
            src={user.avatarUrl} 
            alt="Profile" 
            className="w-20 h-20 rounded-full border-4 border-white/30 bg-slate-700"
          />
          <div>
            <h1 className="text-3xl font-bold mb-1">Hello, {user.name}</h1>
            <p className="text-blue-100 font-mono opacity-80">{user.schoolID} • Class {user.className || 'N/A'}</p>
            {user.schoolName && <p className="text-xs bg-white/20 inline-block px-2 py-1 rounded mt-2">{user.schoolName}</p>}
          </div>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Recent Grades */}
        <div className="bg-white dark:bg-slate-900 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800">
          <h2 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
            <Award className="text-yellow-500" />
            Recent Grades
          </h2>
          {/* Dynamic Recent Grades */}
          <div className="space-y-4">
            {getStudentProfile()?.marks?.slice(0, 3).map((item, idx) => {
                const score = (item.midTerm + item.final) / 2;
                return (
                    <div key={idx} className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800 rounded-lg">
                        <div>
                            <p className="font-semibold text-slate-700 dark:text-slate-300">{item.subject}</p>
                            <p className="text-xs text-slate-500 dark:text-slate-400">Latest Assessment</p>
                        </div>
                        <div className="text-right">
                            <span className="text-lg font-bold text-slate-800 dark:text-white">{calculateGrade(score)}</span>
                            <p className="text-xs text-slate-500 dark:text-slate-400">{score}%</p>
                        </div>
                    </div>
                );
            })}
             {(!getStudentProfile()?.marks || getStudentProfile()?.marks?.length === 0) && (
                 <p className="text-sm text-slate-400 text-center py-4">No grades recorded yet.</p>
             )}
          </div>
        </div>

        {/* Attendance Summary */}
        <div className="bg-white dark:bg-slate-900 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800">
           <h2 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
            <Clock className="text-blue-500" />
            Attendance Overview
          </h2>
          <div className="flex items-center justify-center py-6">
             <div className="relative h-32 w-32 rounded-full border-8 border-slate-100 dark:border-slate-800 flex items-center justify-center">
                <div className="absolute inset-0 border-8 border-blue-600 rounded-full border-t-transparent rotate-[-45deg]" style={{ clipPath: 'polygon(0 0, 100% 0, 100% 100%, 0 100%)' }}></div>
                <div className="text-center">
                    <span className="text-2xl font-bold text-slate-800 dark:text-white">100%</span>
                    <p className="text-xs text-slate-400">Present</p>
                </div>
             </div>
          </div>
        </div>

        {/* Assignments (Dashboard View) */}
        <div className="bg-white dark:bg-slate-900 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 md:col-span-2">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                <ClipboardList className="text-purple-500" />
                Active Assignments
            </h2>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
             {assignments.slice(0, 2).map(assign => (
                 <div key={assign.id} className="border border-slate-200 dark:border-slate-700 rounded-lg p-4 hover:border-blue-300 dark:hover:border-blue-500 transition-colors cursor-pointer group">
                    <div className="flex justify-between items-start mb-2">
                        <span className="bg-purple-100 dark:bg-purple-900/30 text-purple-700 dark:text-purple-300 text-xs px-2 py-1 rounded">{assign.subject}</span>
                        <span className="text-xs text-slate-400">Due {assign.dueDate}</span>
                    </div>
                    <h3 className="font-semibold text-slate-700 dark:text-slate-200 group-hover:text-blue-600 dark:group-hover:text-blue-400 truncate">{assign.title}</h3>
                    <p className="text-sm text-slate-500 dark:text-slate-400 mt-1 line-clamp-2">{assign.content}</p>
                </div>
             ))}
             {assignments.length === 0 && (
                <p className="col-span-full text-center text-slate-400 py-4">No assignments due.</p>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default StudentDashboard;
